//! Sycamore: server-rendered with `render_to_string`, hydrated with `hydrate`.

use bench_common::COUNTER_START;
use sycamore::prelude::*;

/// Library name, which names the files generated by wasm-bindgen.
pub const LIB: &str = "counter_sycamore";

/// A button that increments the number next to it.
#[component]
pub fn App() -> View {
    let count = create_signal(COUNTER_START);
    view! {
        button(id="inc", on:click=move |_| count.set(count.get() + 1)) { "+1" }
        span(id="count") { (count.get()) }
    }
}

/// The server HTML.
#[cfg(not(target_arch = "wasm32"))]
pub fn page() -> String {
    bench_common::counter_page(LIB, &sycamore::render_to_string(App))
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen::prelude::wasm_bindgen(start)]
pub fn start() {
    bench_common::mark("data-start");
    // Synchronous: listeners are attached when it returns.
    sycamore::hydrate(App);
    bench_common::mark("data-ready");
}
